<?php
session_start(); if(!isset($_SESSION['user_id'])){ header('Location: login.php'); exit; }
if(($_SESSION['role']??'')=='admin'){ header('Location: admin_dashboard.php'); exit; }
$data=json_decode(file_get_contents(__DIR__.'/fake_db.json'),true); $uid=$_SESSION['user_id']; $my=[];
foreach($data['complaints'] as $c){ if($c['user_id']==$uid) $my[]=$c; }
$total=count($my); $pend=0; $res=0; foreach($my as $c){ $s=strtolower($c['status']); if($s=='pending')$pend++; if($s=='resolved'||$s=='closed')$res++; }
?>
